import {Body,Controller,ForbiddenException,Get,Injectable,Module,NotFoundException,Param,ParseUUIDPipe,Post,Query,Req} from '@nestjs/common';
import {ApiBearerAuth,ApiProperty,ApiTags} from '@nestjs/swagger';
import {IsDateString,IsIn,IsString,IsUUID,Length,Matches} from 'class-validator';
import {Membership,Prisma,RequestStatus} from '@prisma/client';
import {Database} from '../database.module';
import {Roles,TenantRequest} from '../auth/auth.module';
import {PageDto,paginated} from '../common/page.dto';
import {audit,dateOnly,DecisionDto,decisionComment,fail,privileged,selfEmployee} from '../common/domain';
export class ClaimTypeDto {
 @ApiProperty() @IsString() @Length(1,30) code:string;
 @ApiProperty() @IsString() @Length(1,150) name:string;
}
export class ClaimDto {
 @ApiProperty() @IsUUID() typeId:string;
 @ApiProperty() @IsDateString({strict:true}) @Matches(/^\d{4}-\d{2}-\d{2}$/) date:string;
 @ApiProperty({example:'25.50'}) @IsString() @Matches(/^(0|[1-9]\d{0,11})(\.\d{1,2})?$/) amount:string;
 @ApiProperty() @IsString() @Length(1,2000) description:string;
 @ApiProperty({enum:['PAYROLL','BANK_TRANSFER']}) @IsIn(['PAYROLL','BANK_TRANSFER']) paymentMethod:string;
}
export class PayClaimDto {
 @ApiProperty() @IsDateString({strict:true}) @Matches(/^\d{4}-\d{2}-\d{2}$/) paymentDate:string;
 @ApiProperty() @IsString() @Length(1,100) paymentReference:string;
}
@Injectable()
export class ClaimsService {
 constructor(private db:Database){}
 async types(m:Membership,q:PageDto){
  const where={companyId:m.companyId};
  const [data,total]=await this.db.$transaction([this.db.claimType.findMany({where,orderBy:{code:'asc'},skip:(q.page-1)*q.pageSize,take:q.pageSize}),this.db.claimType.count({where})]);return paginated(data,total,q);
 }
 async createType(m:Membership,d:ClaimTypeDto){
  return this.db.$transaction(async tx=>{
   const data=await tx.claimType.create({data:{...d,companyId:m.companyId}});
   await audit(tx,m,'CLAIM_TYPE_CREATED',data.id);return {data};
  });
 }
 async create(m:Membership,d:ClaimDto){
  if(new Prisma.Decimal(d.amount).lte(0)) fail('INVALID_AMOUNT','Claim amount must be greater than zero.');
  return this.db.$transaction(async tx=>{
   const e=await selfEmployee(tx,m);
   if(!await tx.claimType.findFirst({where:{id:d.typeId,companyId:m.companyId,active:true}})) throw new NotFoundException('Claim type not found.');
   if(dateOnly(d.date)<e.joinedDate) fail('CLAIM_BEFORE_EMPLOYMENT','Claim date precedes employment.');
   const data=await tx.claim.create({data:{...d,date:dateOnly(d.date),employeeId:e.id,managerId:e.managerId,companyId:m.companyId}});
   await audit(tx,m,'CLAIM_DRAFT_CREATED',data.id);return {data};
  },{isolationLevel:'Serializable'});
 }
 async list(m:Membership,q:PageDto,mode:'own'|'all'|'pending'){
  let where:Prisma.ClaimWhereInput={companyId:m.companyId};
  if(mode==='own') where.employeeId=(await selfEmployee(this.db,m)).id;
  if(mode==='pending') where={...where,status:{in:['PENDING_MANAGER','PENDING_FINANCE']},...(privileged(m,['OWNER'])?{}:{OR:[...(privileged(m,['FINANCE'])?[{status:'PENDING_FINANCE' as const}]:[]),...(m.employeeId?[{status:'PENDING_MANAGER' as const,managerId:m.employeeId}]:[])]})};
  const [data,total]=await this.db.$transaction([this.db.claim.findMany({where,orderBy:{createdAt:'desc'},skip:(q.page-1)*q.pageSize,take:q.pageSize}),this.db.claim.count({where})]);
  return paginated(data.map(r=>({...r,amount:r.amount.toFixed(2)})),total,q);
 }
 async submit(m:Membership,id:string){
  return this.db.$transaction(async tx=>{
   const row=await tx.claim.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException();
   if(row.employeeId!==(await selfEmployee(tx,m)).id) throw new ForbiddenException();
   if(row.status!=='DRAFT') fail('INVALID_STATE','Only draft claims can be submitted.',409);
   if(!row.managerId) fail('MANAGER_REQUIRED','Assign a reporting manager before submitting a claim.');
   const data=await tx.claim.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status:'PENDING_MANAGER'}});
   await audit(tx,m,'CLAIM_SUBMITTED',id);return {data};
  },{isolationLevel:'Serializable'});
 }
 async decide(m:Membership,id:string,d:DecisionDto){
  decisionComment(d);
  return this.db.$transaction(async tx=>{
   const row=await tx.claim.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException();
   if(!['PENDING_MANAGER','PENDING_FINANCE'].includes(row.status)) fail('INVALID_STATE','Claim is not awaiting a decision.',409);
   if(row.employeeId===m.employeeId) throw new ForbiddenException('You cannot approve your own claim.');
   const allowed=row.status==='PENDING_MANAGER'?m.employeeId===row.managerId||privileged(m,['OWNER']):privileged(m,['OWNER','FINANCE']);
   if(!allowed) throw new ForbiddenException();
   const status:RequestStatus=d.decision==='REJECT'?'REJECTED':row.status==='PENDING_MANAGER'?'PENDING_FINANCE':'APPROVED';
   const data=await tx.claim.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status,decisionComment:d.comment,decidedBy:m.userId}});
   await audit(tx,m,'CLAIM_'+d.decision,id);return {data};
  },{isolationLevel:'Serializable'});
 }
 async cancel(m:Membership,id:string){
  return this.db.$transaction(async tx=>{
   const row=await tx.claim.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException();
   if(row.employeeId!==(await selfEmployee(tx,m)).id) throw new ForbiddenException();
   if(!['DRAFT','PENDING_MANAGER','PENDING_FINANCE'].includes(row.status)) fail('INVALID_STATE','Only unapproved claims may be cancelled.',409);
   const data=await tx.claim.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status:'CANCELLED'}});
   await audit(tx,m,'CLAIM_CANCELLED',id);return {data};
  },{isolationLevel:'Serializable'});
 }
 async pay(m:Membership,id:string,d:PayClaimDto){
  return this.db.$transaction(async tx=>{
   const row=await tx.claim.findUnique({where:{companyId_id:{companyId:m.companyId,id}}});
   if(!row) throw new NotFoundException();
   if(row.status!=='APPROVED'||row.paymentMethod!=='BANK_TRANSFER') fail('INVALID_STATE','Only approved bank-transfer claims can be marked paid.',409);
   if(dateOnly(d.paymentDate)<row.date) fail('INVALID_PAYMENT_DATE','Payment cannot precede claim date.');
   const data=await tx.claim.update({where:{companyId_id:{companyId:m.companyId,id}},data:{status:'PAID',paymentDate:dateOnly(d.paymentDate),paymentReference:d.paymentReference}});
   await audit(tx,m,'CLAIM_PAID',id);return {data};
  },{isolationLevel:'Serializable'});
 }
}
@ApiBearerAuth() @ApiTags('claims') @Controller('claims')
export class ClaimsController {
 constructor(private service:ClaimsService){}
 @Get('types') types(@Req() r:TenantRequest,@Query() q:PageDto){return this.service.types(r.membership,q);}
 @Post('types') @Roles('OWNER','HR','FINANCE') type(@Req() r:TenantRequest,@Body() d:ClaimTypeDto){return this.service.createType(r.membership,d);}
 @Post() create(@Req() r:TenantRequest,@Body() d:ClaimDto){return this.service.create(r.membership,d);}
 @Get('me') own(@Req() r:TenantRequest,@Query() q:PageDto){return this.service.list(r.membership,q,'own');}
 @Get() @Roles('OWNER','HR','FINANCE') all(@Req() r:TenantRequest,@Query() q:PageDto){return this.service.list(r.membership,q,'all');}
 @Get('pending') pending(@Req() r:TenantRequest,@Query() q:PageDto){return this.service.list(r.membership,q,'pending');}
 @Post(':id/submit') submit(@Req() r:TenantRequest,@Param('id',ParseUUIDPipe) id:string){return this.service.submit(r.membership,id);}
 @Post(':id/decision') decide(@Req() r:TenantRequest,@Param('id',ParseUUIDPipe) id:string,@Body() d:DecisionDto){return this.service.decide(r.membership,id,d);}
 @Post(':id/cancel') cancel(@Req() r:TenantRequest,@Param('id',ParseUUIDPipe) id:string){return this.service.cancel(r.membership,id);}
 @Post(':id/pay') @Roles('OWNER','FINANCE') pay(@Req() r:TenantRequest,@Param('id',ParseUUIDPipe) id:string,@Body() d:PayClaimDto){return this.service.pay(r.membership,id,d);}
}
@Module({controllers:[ClaimsController],providers:[ClaimsService]})
export class ClaimsModule {}

